# Cập nhật web hoc-cung-chinh: lấy bản đang chạy (giữ nguyên giọng nhân bản) + áp phần sửa mới, rồi đóng gói vào thư mục out/
import base64, hashlib, json, os, time, urllib.request, zlib
D = json.loads(zlib.decompress(base64.b64decode("")).decode())
BASE = "https://hoc-cung-chinh.pages.dev/"
def get(path):
    for k in range(5):
        try:
            req = urllib.request.Request(BASE + path + ("&" if "?" in path else "?") + "t=" + str(int(time.time())), headers={"User-Agent": "Mozilla/5.0"})
            return urllib.request.urlopen(req, timeout=120).read()
        except Exception as e:
            print("  thử lại", path, e); time.sleep(3 * (k + 1))
    raise SystemExit("Không tải được " + path)
def put(path, b):
    p = os.path.join("out", path); os.makedirs(os.path.dirname(p) or ".", exist_ok=True); open(p, "wb").write(b)
files = list(D["files"])
for app in ("trung", "anh"):  # giọng nhân bản đang có trên web
    try: man = json.loads(get(app + "/voice/manifest.json"))
    except SystemExit: continue
    files.append(app + "/voice/manifest.json")
    for v in man.get("voices", []):
        idx = app + "/voice/index-" + v["id"] + ".json"; files.append(idx)
        files += [app + "/voice/" + f for f in json.loads(get(idx))["f"]]
files = sorted(set(files)); print("Tải", len(files), "file từ web đang chạy…")
for i, f in enumerate(files):
    p = D["patch"].get(f)
    if p and "full_b64" in p: put(f, base64.b64decode(p["full_b64"])); continue
    if p and "full_z" in p: put(f, zlib.decompress(base64.b64decode(p["full_z"]))); continue
    b = get(f.replace("index.html", "") if f.endswith("index.html") else f)
    if p:
        m = hashlib.md5(b).hexdigest()
        if m == p["md5_new"]: print("  đã là bản mới:", f)
        elif m not in p["from"]: raise SystemExit("Web đang chạy khác bản dự kiến ở " + f + " — báo lại cho Claude.")
        else:
            L = b.decode().split("\n")
            for i1, i2, new, cnt in sorted(p["from"][m], key=lambda o: -o[0]): L[i1:i2] = new.split("\n") if cnt else []
            b = "\n".join(L).encode()
            if hashlib.md5(b).hexdigest() != p["md5_new"]: raise SystemExit("Ghép " + f + " bị sai.")
            print("  đã cập nhật", f)
    put(f, b)
    if i % 50 == 0: print(" ", i + 1, "/", len(files))
open("out/_headers", "w").write(D["headers"])
print("XONG: thư mục out/ có", sum(len(x[2]) for x in os.walk("out")), "file")
